FactMonthlyInventory.sql:
WITH N AS (
 SELECT 0 n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9 UNION ALL SELECT 10 UNION ALL SELECT 11
), P AS (
 SELECT CAST(GETDATE() AS date) TodayDate,DATEADD(month,DATEDIFF(month,0,GETDATE()),0) CurrentMonthStart
), M AS (
 SELECT CASE WHEN n=0 THEN p.TodayDate ELSE DATEADD(day,-1,DATEADD(month,1,DATEADD(month,-n,p.CurrentMonthStart))) END SnapshotDate FROM N CROSS JOIN P p
), Movements AS (
 SELECT r.StockRef StockId,ri.ItemRef ItemId,CAST(r.Date AS date) MovementDate,CAST(ri.Quantity AS decimal(38,4)) Qty FROM INV.InventoryReceipt r JOIN INV.InventoryReceiptItem ri ON ri.InventoryReceiptRef=r.InventoryReceiptID CROSS JOIN P p WHERE r.Date<DATEADD(day,1,p.TodayDate)
 UNION ALL
 SELECT d.StockRef,di.ItemRef,CAST(d.Date AS date),CAST(-di.Quantity AS decimal(38,4)) FROM INV.InventoryDelivery d JOIN INV.InventoryDeliveryItem di ON di.InventoryDeliveryRef=d.InventoryDeliveryID CROSS JOIN P p WHERE d.Date<DATEADD(day,1,p.TodayDate)
), Pairs AS (
 SELECT DISTINCT StockId,ItemId FROM Movements
)
SELECT pr.StockId,pr.ItemId,it.Code ItemCode,m.SnapshotDate,CAST(ISNULL((SELECT SUM(mv.Qty) FROM Movements mv WHERE mv.StockId=pr.StockId AND mv.ItemId=pr.ItemId AND mv.MovementDate<=m.SnapshotDate),0) AS decimal(38,4)) ClosingQty FROM Pairs pr CROSS JOIN M m JOIN INV.Item it ON it.ItemID=pr.ItemId
